import type { Envelope, EventName, EventPayloads } from "./model";

export function dispatch<K extends EventName>(kind: K, ...args: [payload: EventPayloads[K], ...tags: string[]]): Envelope<K> {
  const [payload, ...tags] = args;
  return { kind, payload, tags };
}

export function withAudit<T extends unknown[]>(...values: T): ["audit", ...T] {
  return ["audit", ...values];
}

export function assertCreated(value: unknown): asserts value is EventPayloads["orderCreated"] {
  if (typeof value !== "object" || value === null || !("id" in value) || !("quantity" in value)) {
    throw new Error("An order event must have id and quantity fields");
  }
  if (typeof value.id !== "string" || typeof value.quantity !== "number") {
    throw new Error("Invalid order event fields");
  }
}

import { assertCreated, dispatch, withAudit } from "./client";
import type { EventName, EventPayloads, Handlers, WireName, WirePayload } from "./model";

export const handlers: Handlers<EventPayloads> = {
  onOrderCreated: payload => { payload.quantity.toFixed(); },
  onOrderCancelled: payload => { payload.reason.toUpperCase(); }
};
export const wire: WireName<EventName> = "EVENT:ORDERCREATED";
export const wirePayload: WirePayload<"EVENT:ORDERCREATED"> = { id: "A-17", quantity: 2 };
export const sent = dispatch("orderCreated", wirePayload, "warehouse", "confirmed");
export const audit = withAudit(sent.kind, sent.payload.quantity);

export function ingest(value: unknown) {
  assertCreated(value);
  return dispatch("orderCreated", value, "validated");
}

export interface EventPayloads {
  orderCreated: { id: string; quantity: number };
  orderCancelled: { id: string; reason: string };
}

export type EventName = keyof EventPayloads;
export type WireName<K extends string> = `EVENT:${Uppercase<K>}`;
export type Handlers<P> = {
  [K in keyof P as K extends string ? `on${Capitalize<K>}` : never]: (payload: P[K]) => void;
};
export type WirePayload<N extends string> = {
  [K in EventName]: N extends WireName<K> ? EventPayloads[K] : never;
}[EventName];
export type Envelope<K extends EventName> = {
  kind: K;
  payload: EventPayloads[K];
  tags: string[];
};

